import sys

def solve():
    input_data = sys.stdin.read().split()
    if not input_data:
        return

    iterator = iter(input_data)

    try:
        T = int(next(iterator))
    except StopIteration:
        return

    out_lines = []

    for _ in range(T):
        try:
            N = int(next(iterator))
        except StopIteration:
            break

        adj = [[] for _ in range(N + 1)]

        for _ in range(N - 1):
            u = int(next(iterator))
            v = int(next(iterator))
            adj[u].append(v)
            adj[v].append(u)

        A = [0] * (N + 1)
        for i in range(1, N + 1):
            A[i] = int(next(iterator))

        if N == 1:
            out_lines.append(str(A[1]))
            continue

        parent = [0] * (N + 1)
        children = [[] for _ in range(N + 1)]
        order = []
        stack = [1]
        visited = [False] * (N + 1)
        visited[1] = True

        while stack:
            u = stack.pop()
            order.append(u)
            for v in adj[u]:
                if not visited[v]:
                    visited[v] = True
                    parent[v] = u
                    children[u].append(v)
                    stack.append(v)

        leaves = []
        for u in range(1, N + 1):
            if not children[u]:
                leaves.append(u)

        leaf_or = [0] * (N + 1)
        for u in reversed(order):
            val = A[u]
            if children[u]:
                for v in children[u]:
                    val |= leaf_or[v]
            leaf_or[u] = val

        current_total = 0
        for u in leaves:
            current_total += leaf_or[u]

        bit_counts = [0] * 32
        for u in leaves:
            val = leaf_or[u]
            for b in range(32):
                if (val >> b) & 1:
                    bit_counts[b] += 1

        total_leaves = len(leaves)

        min_security = current_total

        for b in range(32):
            if bit_counts[b] < total_leaves:
                continue

            candidate_security = current_total - (total_leaves * (1 << b))

            valid = True
            for u in leaves:
                new_val = leaf_or[u] ^ (1 << b)
                if new_val == 0:
                    valid = False
                    break

            if valid:
                min_security = min(min_security, candidate_security)

        out_lines.append(str(min_security))

    sys.stdout.write('\n'.join(out_lines) + '\n')

solve()
